      id: envelopeId,
      factor: "secure-enclave",
      domain: "this-device",
      label,
      createdAt: new Date(deps.now()).toISOString(),
      helper: { teamId: session.identity.teamId, bundleId: session.identity.bundleId, minVersion: session.version },
      publicKey: created.publicKeySpki,
