    if (destination === undefined) {
      throw new VaultError("GRANT_DESTINATION_UNRESOLVED", `${teeAddress} has no pinned vault destination to fund from.`, {
        suggestion: "Nothing was signed. Name the source key with --from <label>, or pin one: candle tee enable <address> --vault <address>"
      });
    }
    const fromEntry = vault.index.entries.find((entry) => entry.address === destination && entry.role === "vault");
    if (fromEntry === undefined) {
      throw new VaultError("GRANT_DESTINATION_UNRESOLVED", `Pinned destination ${destination} is not a vault key in this vault.`, {
        suggestion: "Nothing was signed. Name the source key with --from <label>; candle vault status lists this vault's keys."
      });
    }
    assertVaultSigner(fromEntry);
    ctx.deps.stdout.write(`Every funded unit adds to the TEE wallet exposure; the initial float is not a maximum loss.
`);
    const plan = await planTransfer({
      from: fromEntry.address,
      to: teeAddress,
      amount,
      asset,
      rpcUrl: rpcUrl2,
      fetch: ctx.deps.fetch
    });
    const feeQuote = await quoteTransferFee(rpcUrl2, ctx.deps.fetch, plan.from, plan.instructions);
    displayTransferPlan(ctx, plan, feeQuote);
    await confirmLastSix(ctx, teeAddress, "the TEE wallet destination");
    await opened.confirm(`fund ${plan.amount} ${plan.asset} to ${teeAddress}`);
    const secret = await decryptKey(vault, fromEntry.id);
    try {
      let receipt;
      const result = await signAndBroadcastTransfer({
        ctx,
        rpcUrl: rpcUrl2,
        secret64: secret,
        plan,
        beforeBroadcast: async ({ signature, blockhash }) => {
          receipt = {
            signature,
            blockhash,
            from: plan.from,
            amount: plan.amount,
            asset: plan.asset,
            amountRaw: plan.amountRaw.toString(),
            at: new Date(ctx.deps.now()).toISOString(),
            finalized: false
          };
          await saveFundingReceipt(vault, teeEntry.id, receipt, ctx);
        }
      });
      if (result.finalized && receipt) {
        await saveFundingReceipt(vault, teeEntry.id, { ...receipt, finalized: true }, ctx);
      }
      if (ctx.json) {
        writeJson(ctx.deps, {
          ok: result.finalized,
          signature: result.signature,
          tee: teeAddress,
          from: plan.from,
          amount: plan.amount,
          asset: plan.asset,
          finalized: result.finalized
        });
      } else {
        ctx.deps.stdout.write(result.finalized ? `Funded ${teeAddress} with ${plan.amount} ${plan.asset}: ${result.signature}
` : `Submitted ${result.signature}; finality is not yet confirmed. Receipt recorded.
`);
      }
      return result.finalized ? 0 : 3;
    } finally {
      wipe(secret);
    }
