        ok: rebound === undefined || rebound.exit === 0,
        mode: "fresh",
        address,
        label: entry.label,
        vaultDestination: destination.address,
        lifecycle: target.tee?.lifecycle,
        linkedWalletId: target.linkedWalletId ?? null,
        importCalls: importCount.n,
